CREATE TABLE "event_datasets" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"organization_id" uuid NOT NULL,
	"event_id" uuid NOT NULL,
	"name" varchar(200) NOT NULL,
	"file_name" varchar(255) NOT NULL,
	"sheet_name" varchar(120),
	"status" text DEFAULT 'NEEDS_REVIEW' NOT NULL,
	"columns" jsonb NOT NULL,
	"rows" jsonb NOT NULL,
	"row_count" integer NOT NULL,
	"header_row" integer NOT NULL,
	"dropped_columns" jsonb NOT NULL,
	"mapping" jsonb NOT NULL,
	"suggested_by" jsonb,
	"interpretation" jsonb,
	"created_by" uuid,
	"confirmed_by" uuid,
	"confirmed_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "event_datasets_status" CHECK ("event_datasets"."status" in ('NEEDS_REVIEW', 'CONFIRMED')),
	CONSTRAINT "event_datasets_confirmed" CHECK (("event_datasets"."status" = 'CONFIRMED') = ("event_datasets"."confirmed_at" is not null)),
	CONSTRAINT "event_datasets_json_arrays" CHECK (jsonb_typeof("event_datasets"."columns") = 'array' and jsonb_typeof("event_datasets"."rows") = 'array'
      and jsonb_typeof("event_datasets"."mapping") = 'array' and jsonb_typeof("event_datasets"."dropped_columns") = 'array'),
	CONSTRAINT "event_datasets_row_count" CHECK ("event_datasets"."row_count" between 0 and 20000 and "event_datasets"."row_count" = jsonb_array_length("event_datasets"."rows")),
	CONSTRAINT "event_datasets_name_not_blank" CHECK (length(trim("event_datasets"."name")) > 0)
);
